feed:
{{ config.title }}
{%- if term %} - {{ term.name }}
{%- elif section.title %} - {{ section.title }}
{%- endif -%}

{%- if config.description %}
{{ config.description }}
{%- endif %}


{{ last_updated | date(format="%+") }}
{{ feed_url | safe }}
{%- for page in pages | slice(end=config.extra.number_feed_items) %}


    {%- if page.components.0 == "recommendations" -%}Added recommendation: {% endif -%}
    {{ page.title }}
    {{ page.date | date(format="%+") }}
    {{ page.updated | default(value=page.date) | date(format="%+") }}


        {%- if page.authors -%}
          {{ page.authors[0] }}
        {%- elif config.author -%}
          {{ config.author }}
        {%- else -%}
          Unknown
        {%- endif -%}



    {{ page.permalink | safe }}
    {% if page.summary %}
    {{ page.summary }}
    {% endif %}

    {% if page.extra.in_reply_to -%}
      <a class="u-in-reply-to" href="{{- page.extra.in_reply_to  }}">In reply to</a>
    {%- endif -%}
    {% if page.components.0 == "recommendations" -%}
    {% filter escape_xml %}
      {{page.title}} - Feed
    {% endfilter %}
    {%- endif -%}
    {% if page.components.0 == "photos" -%}
      {% for asset in page.assets -%}
        {%- if asset is matching("[.](jpg|png)$") -%}
        {% set image = resize_image(path=asset, width=320, op="fit_width") %}
        <img src="{{ image.url }}" />
        {%- endif %}
      {%- endfor %}
    {%- endif -%}
    {{ page.content }}

{%- endfor %}
